    @Test
    fun monochrome1Bit() {
        val bytes = hex("49492a00460000002b0f554d0a0f5517b0ff54d5a0ff51750fb24d550ff81755ff22d555ff807555480000000100000048000000010000004c61766336322e31312e313030000e00fe000400010000000000000000010400010000001000000001010400" +
            "01000000100000000201030001000000010000000301030001000000010000000601030001000000010000001101040001000000080000001501030001000000010000001601040001000000aa0a00001701040001000000200000001a01050001000000" +
            "280000001b0105000100000030000000280103000100000002000000310102000e0000003800000000000000")
        assertEquals(ImageFormat.TIFF, KiteImage.detect(bytes))
        val bm = KiteImage.decode(bytes)
        assertEquals(16, bm.width); assertEquals(16, bm.height)
        val exp = hex("000000000000ffffff000000ffffff000000ffffffffffff000000000000000000000000ffffffffffffffffffffffff000000ffffff000000ffffff000000ffffff000000ffffff000000ffffff000000000000ffffffffffff000000ffffff00000000" +
            "0000000000000000ffffff000000ffffff000000000000000000000000000000ffffffffffffffffffffffff000000ffffff000000ffffff000000ffffff000000ffffff000000000000000000ffffff000000ffffffffffffffffffffffff000000ffff" +
            "ffffffff000000000000000000000000ffffffffffffffffffffffffffffffffffffffffffffffff000000ffffff000000ffffff000000ffffff000000000000ffffffffffff000000ffffff000000ffffff000000ffffffffffff000000ffffff000000" +
            "000000000000000000000000ffffffffffffffffffffffffffffffffffffffffffffffff000000ffffff000000ffffff000000000000000000ffffff000000ffffffffffffffffff000000ffffff000000ffffff000000000000000000000000ffffffff" +
            "ffffffffffffffffffffff000000ffffffffffff000000000000ffffff000000000000ffffff000000000000ffffffffffff000000ffffff000000ffffff000000ffffff000000ffffff000000ffffff000000000000000000000000ffffffffffffffff" +
            "ffffffffffffffffffffffffffffffffffffff000000000000000000000000000000000000ffffff000000ffffffffffffffffff000000ffffff000000ffffff000000ffffff000000ffffffffffffffffffffffffffffffffffffffffffffffffffffff" +
            "000000000000ffffff000000000000000000ffffff000000ffffffffffff000000ffffff000000ffffff000000ffffff000000ffffff000000ffffff000000ffffff000000ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff00" +
            "0000000000000000000000000000000000000000000000ffffffffffffffffff000000ffffff000000ffffff000000ffffff000000ffffff000000ffffff000000ffffff")
        for (y in 0 until 16) for (x in 0 until 16) {
            val i = (y * 16 + x) * 3
            val p = bm[x, y]
            for ((c, shift) in intArrayOf(16, 8, 0).withIndex()) {
                val d = abs((exp[i + c].toInt() and 0xFF) - ((p shr shift) and 0xFF))
                assertTrue(d <= 1, "monochrome1Bit ($x,$y) ch$c diff $d")
            }
        }
    }
